retc_t str_to_sym ( struct ps_prochandle * ph , const char * name , GElf_Sym * symp ) { map_info_t * mip ; if ( ph -> pp_lmaplist . ml_head == NULL ) { return ( str_map_sym ( name , & ( ph -> pp_execmap ) , symp , NULL ) ) ; } for ( mip = ph -> pp_lmaplist . ml_head ; mip ; mip = mip -> mi_next ) { if ( str_map_sym ( name , mip , symp , NULL ) == RET_OK ) { return ( RET_OK ) ; } } return ( RET_FAILED ) ; } 